-- ============================================================================
-- PARTIE 18 — Contenu du module 6 « Langage » (3 séquences)
-- Source : Projet pédagogique Koalakids (le jeune enfant apprend à parler pour
-- penser le monde, visages et regards, répondre aux sollicitations, vocabulaire
-- employé, mettre des mots sur les actions et les émotions).
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 18.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Apprendre à parler, c'est apprendre à penser : l'enfant a besoin d'adultes qui lui parlent, le regardent et lui répondent.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire pourquoi parler à l'enfant, le regarder et répondre à ses sollicitations soutient son langage et sa pensée, et d'ajuster sa façon de lui parler.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Langage et communication"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un enfant qui cherche à se faire comprendre (mots, gestes, regards), sans le nommer."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Apprendre à parler ne sert pas seulement à communiquer : c'est ce qui permet à l'enfant de penser.", "idees": ["Dès le ventre de sa mère, le bébé est bercé par la musique de sa ou de ses langues familiales. Avec l'aide des adultes qui soutiennent ses essais, il apprend à reconnaître le nom des objets et à les nommer : il se fabrique sa « bibliothèque de mots ».", "Les enfants lisent plus facilement les expressions des visages que les mots des phrases. Ils ont besoin de bien voir le visage des adultes, et surtout leurs yeux, pour comprendre leurs intentions.", "On réagit aux sollicitations de l'enfant : l'absence de réaction est très angoissante, il se sent perdu et abandonné. On répond à ses expressions et on met des mots sur ce qu'il observe et vit."], "support": "Projet pédagogique Koalakids, « Le jeune enfant apprend à parler pour penser le monde »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un moment vécu cette semaine où un enfant cherchait à se faire comprendre, sans le nommer. On analyse ce que fait l'adulte, pas ce qu'est l'enfant.", "questions": ["Que s'est-il passé ? (ce que l'enfant a exprimé : regard, geste, mot)", "L'enfant voyait-il mon visage et mes yeux ? Ai-je réagi à sa sollicitation ?", "Quels mots ai-je mis sur ce qu'il vivait ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : me mettre à hauteur de l'enfant pour qu'il voie mon visage et mes yeux quand je lui parle.", "Exemple : répondre à chaque sollicitation d'un enfant, même d'un regard ou d'un mot.", "Exemple : mettre des mots sur ce que fait ou observe un enfant."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : analyse d'une situation vécue, avec un focus sur les mots que nous employons."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 6 % 1/3 %';
-- FIN 18.1a

-- ---------------------------------------------------------------------------
-- 18.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Une bibliothèque de mots", "paragraphes": ["Apprendre à parler ne sert pas seulement à nommer les choses et à se faire comprendre. Cela permet aussi et surtout à l'enfant **d'apprendre à penser**. Peu à peu, il se fabrique sa « bibliothèque de mots ».", "Cette première séance pose un repère : pour parler, l'enfant a besoin d'adultes qui **lui parlent, le regardent et lui répondent**."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Parler pour penser :** avec l'aide des adultes, l'enfant apprend le nom des objets et passe de la perception à la représentation.", "**Le visage compte :** les enfants lisent les expressions des visages plus facilement que les mots. Ils ont besoin de voir nos yeux.", "**Répondre :** l'absence de réaction est très angoissante. On répond à ses sollicitations et on met des mots sur ce qu'il vit."]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour parler à un jeune enfant.", "plutot": ["Me mettre à hauteur de l'enfant pour qu'il voie mon visage.", "Répondre à ses regards, ses gestes et ses mots.", "Mettre des mots sur ce qu'il fait et ressent.", "Parler avec lui plutôt que de lui."], "eviter": ["Parler à l'enfant sans le regarder.", "Ne pas réagir quand il me sollicite.", "Parler de lui entre adultes comme s'il n'était pas là.", "Parler négativement de lui ou de ses parents devant lui."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à un enfant que vous accompagnez. Comment fait-il comprendre ce qu'il veut avant de savoir le dire ? Comment lui répondez-vous ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à mettre des mots sur ce que l'on voit.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Parler à hauteur d'yeux", "etapes": [{"titre": "Me mettre à sa hauteur.", "texte": "Pour qu'il voie mon visage et mes yeux quand je lui parle."}, {"titre": "Répondre.", "texte": "À son regard, son geste ou son mot : je réagis, même brièvement."}, {"titre": "Mettre des mots.", "texte": "Sur ce qu'il fait, observe ou ressent."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 6 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 18.1b

-- ---------------------------------------------------------------------------
-- 18.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Nos mots reflètent la façon dont nous considérons l'enfant : on regarde ceux que l'on emploie.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de repérer dans une situation vécue sur le site les mots qui aident l'enfant à comprendre ce qui lui arrive et ceux qui le jugent ou l'ignorent, et de dire ce qu'il dirait autrement.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Langage et communication"}, "duree_min": 45, "materiel": ["Paperboard (pour noter les mots employés, sans nom)", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Nos mots disent comment nous considérons l'enfant : on les choisit pour qu'il puisse comprendre.", "idees": ["On veille au vocabulaire employé : c'est la couche de l'enfant qui est changée, pas l'enfant ni « ses fesses ». Le langage adressé doit lui permettre d'envisager le soin, non juger son état de « non-propreté ».", "Tout ce que dit et fait l'adulte s'imprime dans le cerveau de l'enfant, particulièrement vulnérable à cet âge. On ne parle pas négativement des enfants ou de leurs parents en leur présence, ni de l'enfant entre nous sans l'inclure dans la conversation.", "On prévient l'enfant et on lui explique ce qui lui arrive ou va lui arriver, on échange avec lui, on lui parle et on l'écoute, notamment pendant les soins."], "support": "Projet pédagogique Koalakids, « Veiller au langage et au vocabulaire employé »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un moment vécu cette semaine (un soin, un repas, un échange) où les mots employés ont compté, sans nommer l'enfant. On analyse les mots, pas la personne.", "questions": ["Qu'ai-je dit ou entendu ? (les mots exacts)", "Que comprend l'enfant de ce qui lui arrive ?", "Ces mots l'aident-ils à comprendre, ou jugent-ils l'enfant ou son état ?", "Que dire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : prévenir l'enfant avant chaque soin en lui disant ce que je vais faire.", "Exemple : parler de la couche, pas de l'enfant, quand je le change.", "Exemple : répondre à un enfant qui me sollicite, même brièvement."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur les mots mis sur ce que l'enfant vit."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 6 % 2/3 %';
-- FIN 18.2a

-- ---------------------------------------------------------------------------
-- 18.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Des mots qui disent comment on considère l'enfant", "paragraphes": ["Nos mots reflètent la façon dont le soin et l'enfant sont considérés. Ce que dit l'adulte **s'imprime dans le cerveau de l'enfant**, particulièrement vulnérable à cet âge.", "Cette séance propose d'analyser une situation vécue en regardant les mots employés, jamais la personne qui les a dits."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Il est changé sans un mot", "texte": "On enlève la couche de Mila sans rien lui dire, en parlant à une collègue de la réunion de l'après-midi.", "analyse": "faire un soin sans verbaliser ce qui arrive à l'enfant fait partie des violences éducatives ordinaires. On le prévient, on lui explique ce qui va se passer, on échange avec lui, on lui parle et on l'écoute."}, {"lettre": "B", "titre": "« Qu'est-ce que tu as encore fait ! »", "texte": "En changeant Jules, un collègue lance : « Qu'est-ce que tu as encore fait ! »", "analyse": "c'est la couche de l'enfant qui est changée, pas l'enfant. Le langage doit lui permettre d'envisager le soin, non juger son état de « non-propreté ». On parle de la couche, simplement."}, {"lettre": "C", "titre": "Il parle, personne ne répond", "texte": "Tom tend un jouet en disant « ça ! ». Les adultes sont occupés, personne ne réagit.", "analyse": "l'absence de réaction est très angoissante pour un jeune enfant, qui se sent perdu et abandonné. On répond d'un regard ou d'un mot et on met des mots sur ce qu'il montre : « Tu me montres le camion. »"}]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour choisir ses mots avec un jeune enfant.", "plutot": ["Prévenir l'enfant et lui expliquer ce qui va se passer.", "Parler de la couche, pas de l'enfant ni de son corps.", "Répondre quand il me sollicite.", "Inclure l'enfant dans la conversation."], "eviter": ["Faire un soin sans verbaliser.", "Juger l'enfant ou son état de « non-propreté ».", "Parler négativement de lui ou de ses parents devant lui.", "Parler de lui entre adultes comme s'il était transparent."]}$kk$),
  (3,'reflexion',$kk${"question": "Y a-t-il une expression que l'on emploie souvent sur le site à propos des enfants et qui mériterait d'être dite autrement ? Laquelle ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions avant de parler", "etapes": [{"titre": "Est-ce que je lui parle ?", "texte": "Je m'adresse à lui, pas seulement à mes collègues."}, {"titre": "Peut-il comprendre ?", "texte": "Je dis ce qui se passe ou va se passer."}, {"titre": "Est-ce respectueux ?", "texte": "Mes mots ne jugent ni l'enfant, ni son état, ni ses parents."}], "note": "On analyse les mots, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 6 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 18.2b

-- ---------------------------------------------------------------------------
-- 18.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Mettre des mots, c'est offrir à l'enfant de quoi comprendre ce qu'il vit et le dire à son tour.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée dans la façon de parler à l'enfant, et l'équipe a choisi une pratique commune pour mettre des mots sur ce que les enfants vivent.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Langage et communication"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Les mots que je mets sur ce que l'enfant vit, il les reprendra peu à peu pour se faire comprendre.", "idees": ["On met des mots sur ses actions pour qu'il puisse les comprendre, et sur ses émotions pour qu'il puisse les comprendre et les apprivoiser.", "On nomme aussi ce que l'on ressent dans la relation à l'enfant (« Je suis content de te voir ce matin ») : il comprend le sens des émotions et pourra les utiliser à son tour.", "Notre communication verbale et non verbale (mots doux, regards tendres et soutenants, sourires, berceuses, joie d'être avec eux) participe au bien-être et à la joie d'être ensemble."], "support": "Projet pédagogique Koalakids, « Que faire concrètement pour accompagner les enfants dans leurs émotions ? »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'a fait l'enfant quand j'ai mis des mots sur ce qu'il vivait ? Qu'est-ce qui a changé, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 6. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 6 % 3/3 %';
-- FIN 18.3a

-- ---------------------------------------------------------------------------
-- 18.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Offrir ses mots", "paragraphes": ["Quand l'adulte met des mots sur ce que l'enfant fait et ressent, il lui **offre de quoi comprendre ce qu'il vit**. Peu à peu, l'enfant reprend ces mots pour se faire comprendre à son tour.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour mettre des mots sur ce que les enfants vivent."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Mettre des mots sur ses actions** pour qu'il puisse les comprendre.", "**Mettre des mots sur ses émotions** pour qu'il puisse les comprendre et les apprivoiser.", "**Nommer aussi ce que l'on ressent :** « Je suis content de te voir ce matin ». L'enfant apprend le sens des émotions."]}$kk$),
  (2,'reflexion',$kk${"question": "Dans quel moment de la journée vous arrive-t-il de parler le moins aux enfants ? Qu'est-ce qui vous aiderait à y mettre plus de mots ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui rendrait la parole plus facile.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple, que chacun décrit de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 6 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 18.3b

-- ---------------------------------------------------------------------------
-- 18c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 6 %/3 %' order by m.ordre;
-- FIN 18c
